def _size_lc(B, d):
    """(size, path length) of B whose root is at depth d"""
    if B == None:
        return (0, 0)
    else:
        (s1, l1) = _size_lc(B.left, d + 1)
        (s2, l2) = _size_lc(B.right, d + 1)
        return (1 + s1 + s2, d + l1 + l2)

def average_depth(B):
    (s, lc) = _size_lc(B, 0)
    return lc / s
```

