def bfs_list(B):
    L = []
    if B != None:
        q = Queue()
        q.enqueue(B)
        while not q.isempty():
            B = q.dequeue()
            L.append(B.key)
            if B.left != None:
                q.enqueue(B.left)
            if B.right != None:
                q.enqueue(B.right)
    return L
```

Annexe de l'examen : arbre vide `None`, sinon `BinTree` (`key`, `left`, `right`) ; file `Queue()` avec `enqueue`, `dequeue`, `isempty` ; seuls `len`, `range`, `append`, et `min`/`max` sur deux entiers.

```python
def width(B):
    w_max = 0
    if B != None:
        q = Queue()
        q.enqueue(B)
        q.enqueue(None)
        w = 0
        while not q.isempty():
            B = q.dequeue()
            if B == None:
                w_max = max(w, w_max)
                if not q.isempty():
                    q.enqueue(None)
                w = 0
            else:
                w = w + 1
                if B.left != None:
                    q.enqueue(B.left)
                if B.right != None:
                    q.enqueue(B.right)
    return w_max
```

Corrigé officiel : le marqueur `None` sépare les niveaux ; on le réenfile seulement si la file n'est pas vide (sinon boucle infinie).

```python
def get_node(B, lvl, n):
    if B == None:
        return None
    q = Queue()
    q.enqueue(B)
    q.enqueue(None)
    (cur, i) = (0, 0)
    while not q.isempty() and cur <= lvl:
        B = q.dequeue()
        if B == None:
            (cur, i) = (cur + 1, 0)
            if not q.isempty():
                q.enqueue(None)
        else:
            if cur == lvl and i == n:
                return B.key
            i = i + 1
            if B.left != None:
                q.enqueue(B.left)
            if B.right != None:
                q.enqueue(B.right)
    return None
```

On s'arrête dès que le nœud est trouvé ou que le niveau `lvl` est dépassé.

```python
def degenerate(B):
    while B != None and (B.left == None or B.right == None):
        if B.left == None:
            B = B.right
        else:
            B = B.left
    return B == None
```

Un seul chemin à suivre : une boucle suffit. On sort sur `None` (dégénéré) ou sur un point double.

```python
def _complete(B):
    """height of B if B is complete, -2 otherwise"""
    if B == None:
        return -1
    hl = _complete(B.left)
    if hl == -2:
        return -2
    hr = _complete(B.right)
    if hr != hl:
        return -2
    return hl + 1

def complete(B):
    return _complete(B) != -2
```

Complet : les deux sous-arbres sont complets et de même hauteur. La valeur $-2$ signale l'échec et coupe le parcours.

```python
def _test(B, p):
    """p: key of B's parent"""
    if B == None:
        return True
    elif B.key < p:
        return False
    else:
        return _test(B.left, B.key) and _test(B.right, B.key)

def priority(B):
    return _test(B, 0)
```

Corrigé officiel : la clé du père descend en paramètre ($0$ pour la racine, les clés étant $>0$).

```python
def transpose(B):
    if B == None:
        return None
    else:
        return BinTree(2 * B.key, transpose(B.right), transpose(B.left))
```

Un nœud créé par appel ; les sous-arbres sont échangés.

```python
def _build(V, i):
    if i >= len(V) or V[i] == None:
        return None
    else:
        return BinTree(V[i], _build(V, 2 * i), _build(V, 2 * i + 1))

def from_hier(V):
    return _build(V, 1)
```

Le nœud $i$ a ses fils en $2i$ et $2i+1$ ; hors du vecteur, l'arbre est vide.

```python
def _hmax(B, i):
    """largest hierarchical number in B, whose root is number i"""
    if B == None:
        return 0
    else:
        return max(i, max(_hmax(B.left, 2 * i), _hmax(B.right, 2 * i + 1)))

def _fill(B, V, i):
    if B != None:
        V[i] = B.key
        _fill(B.left, V, 2 * i)
        _fill(B.right, V, 2 * i + 1)

def to_hier(B):
    V = []
    for i in range(_hmax(B, 1) + 1):
        V.append(None)
    _fill(B, V, 1)
    return V
```

