```

La taille d'un nœud se calcule après celles de ses fils (traitement suffixe), sans second parcours.

```python
def _sh(B, x, n):
    if B == None:
        return None
    elif B.key == x:
        return n
    else:
        r = _sh(B.left, x, 2 * n)
        if r == None:
            r = _sh(B.right, x, 2 * n + 1)
        return r

def search_hier(B, x):
    return _sh(B, x, 1)
```

Le numéro descend en paramètre ; on ne cherche à droite que si la gauche a échoué.

```python
def _find(B, x):
    """subtree of B whose root is x, None if absent"""
    if B == None or B.key == x:
        return B
    else:
        r = _find(B.left, x)
        if r == None:
            r = _find(B.right, x)
        return r

def _depth(B, y):
    """depth of y in B, -1 if absent"""
    if B == None:
        return -1
    elif B.key == y:
        return 0
    else:
        d = _depth(B.left, y)
        if d == -1:
            d = _depth(B.right, y)
        if d == -1:
            return -1
        return d + 1

def get_kinship(B, x, y):
    A = _find(B, x)
    if A != None:
        d = _depth(A, y)
        if d != -1:
            return d
    A = _find(B, y)
    if A != None:
        return _depth(A, x)
    return -1
```

Même branche : l'un est ancêtre de l'autre. On cherche `y` sous `x`, sinon `x` sous `y`.

```python
def search_code(T, c):
    if T.left == None:
        if T.key == c:
            return ""
        else:
            return None
    else:
        r = search_code(T.left, c)
        if r != None:
            return "0" + r
        r = search_code(T.right, c)
        if r != None:
            return "1" + r
        return None
```

Localement complet : un nœud sans fils gauche est une feuille. Le code se construit en remontant.

```python
def increasing(B):
    if B == None:
        return True
    q = Queue()
    q.enqueue(B)
    q.enqueue(None)
    (prev, cur) = (0, 0)
    ok = True
    while ok and not q.isempty():
        B = q.dequeue()
        if B == None:
            ok = cur > prev
            (prev, cur) = (cur, 0)
            if not q.isempty():
                q.enqueue(None)
        else:
            cur = cur + 1
            if B.left != None:
                q.enqueue(B.left)
            if B.right != None:
                q.enqueue(B.right)
    return ok
```

