def list_sum_limit(B, limit):
    L = []
    if B != None:
        q = Queue()
        q.enqueue(B)
        q.enqueue(None)
        s = 0
        while not q.isempty():
            B = q.dequeue()
            if B == None:
                if s < limit:
                    L.append(s)
                s = 0
                if not q.isempty():
                    q.enqueue(None)
            else:
                s = s + B.key
                if B.left != None:
                    q.enqueue(B.left)
                if B.right != None:
                    q.enqueue(B.right)
    return L
```

